//! FSR 3 (FidelityFX Super Resolution 3.1 upscaling) through AMD's official
//! FidelityFX API library, loaded at runtime with `libloading` (feature
//! `fsr3`). The bindings are generated by bindgen from the library's headers
//! (`ffx/generate-bindings.sh`); no C++ is compiled.
//!
//! * The library is `amd_fidelityfx_vk.dll` from `PrebuiltSignedDLL/` of the
//!   FidelityFX SDK v1.1.4 (MIT). It is not in the repository: it is looked
//!   for next to the executable only.
//! * It is loaded on Windows x86_64 only. Elsewhere (Windows ARM64, Linux,
//!   macOS) detection reports FSR 3 unavailable and the registry falls back
//!   to FSR 1.
//! * Detection (the registry's probe): the library is present and loadable,
//!   its entry points resolve, and a context initialises on the renderer's
//!   device (which also checks that the GPU is supported).
//!
//! Every `unsafe` block of the FSR 3 path lives in this module.

mod api;
#[allow(
    non_camel_case_types,
    non_snake_case,
    non_upper_case_globals,
    dead_code,
    clippy::all
)]
mod bindings;
mod mapping;
mod upscaler;

use std::path::Path;
use std::sync::Arc;

use faset_render::GpuHandles;

use crate::{Backend, UpscaleError, Upscaler, UpscalerKind};
use api::FfxApi;
use mapping::{FfxDevice, LIBRARY_NAME};

/// True where the library is loaded.
const SUPPORTED_PLATFORM: bool = cfg!(all(target_os = "windows", target_arch = "x86_64"));

fn unavailable(reason: String) -> UpscaleError {
    UpscaleError::Unavailable {
        kind: UpscalerKind::Fsr3,
        reason,
    }
}

/// What the FSR 3 backend needs from the registry's context.
pub(crate) trait Host {
    /// The device, as the library's Vulkan backend takes it.
    fn ffx_device(&self) -> FfxDevice;

    /// Builds the upscaler over a loaded library.
    fn build(
        &self,
        api: Arc<dyn FfxApi>,
        device: FfxDevice,
    ) -> Result<Box<dyn Upscaler>, UpscaleError>;
}

impl Host for GpuHandles {
    fn ffx_device(&self) -> FfxDevice {
        FfxDevice {
            device: self.device.handle(),
            physical: self.physical,
            get_device_proc_addr: self.instance.fp_v1_0().get_device_proc_addr,
        }
    }

    fn build(
        &self,
        api: Arc<dyn FfxApi>,
        device: FfxDevice,
    ) -> Result<Box<dyn Upscaler>, UpscaleError> {
        Ok(Box::new(upscaler::Fsr3::new(self, api, device)?))
    }
}

type Loader = Box<dyn Fn() -> Result<Arc<dyn FfxApi>, UpscaleError>>;

/// The registry entry of FSR 3.
pub(crate) struct Fsr3Backend {
    load: Loader,
}

impl Fsr3Backend {
    /// The official library, next to the executable.
    pub(crate) fn system() -> Self {
        Self::with_loader(Box::new(load_system))
    }

    pub(crate) fn with_loader(load: Loader) -> Self {
        Self { load }
    }
}

impl<C: Host> Backend<C> for Fsr3Backend {
    fn kind(&self) -> UpscalerKind {
        UpscalerKind::Fsr3
    }

    fn probe(&self, host: &C) -> Result<(), UpscaleError> {
        let api = (self.load)()?;
        upscaler::detect(&*api, &host.ffx_device())
    }

    fn create(&self, host: &C) -> Result<Box<dyn Upscaler>, UpscaleError> {
        let api = (self.load)()?;
        host.build(api, host.ffx_device())
    }
}

/// Loads the library from the executable's directory.
fn load_system() -> Result<Arc<dyn FfxApi>, UpscaleError> {
    if !SUPPORTED_PLATFORM {
        return Err(unavailable(
            "the FidelityFX library is only loaded on Windows x86_64".into(),
        ));
    }
    let exe = std::env::current_exe()
        .map_err(|e| unavailable(format!("cannot locate the executable: {e}")))?;
    let dir = exe
        .parent()
        .ok_or_else(|| unavailable("the executable has no directory".into()))?;
    load_from(&dir.join(LIBRARY_NAME))
}

/// Loads the library at `path`.
fn load_from(path: &Path) -> Result<Arc<dyn FfxApi>, UpscaleError> {
    api::load(path).map_err(unavailable)
}

#[cfg(test)]
mod tests {
    use std::ptr::NonNull;
    use std::sync::Mutex;

    use ash::vk::{self, Handle};
    use faset_render::{FrameCtx, ImageHandle, UpscaleInputs};

    use super::bindings as ffx;
    use super::*;
    use crate::{Extent2D, Quality, Registry};

    /// Does nothing.
    struct Stub;

    impl Upscaler for Stub {
        fn render_extent(&self, display: Extent2D, _quality: Quality) -> Extent2D {
            display
        }
        fn jitter(&self, _frame_index: u32) -> faset_render::glam::Vec2 {
            faset_render::glam::Vec2::ZERO
        }
        fn execute(&mut self, _ctx: &mut FrameCtx<'_>, inputs: &UpscaleInputs) -> ImageHandle {
            inputs.colour
        }
    }

    unsafe extern "system" fn no_proc(
        _: vk::Device,
        _: *const std::ffi::c_char,
    ) -> vk::PFN_vkVoidFunction {
        None
    }

    /// A registry context without a GPU.
    struct FakeHost;

    impl Host for FakeHost {
        fn ffx_device(&self) -> FfxDevice {
            FfxDevice {
                device: vk::Device::from_raw(0x10),
                physical: vk::PhysicalDevice::from_raw(0x20),
                get_device_proc_addr: no_proc,
            }
        }
        fn build(
            &self,
            _api: Arc<dyn FfxApi>,
            _device: FfxDevice,
        ) -> Result<Box<dyn Upscaler>, UpscaleError> {
            Ok(Box::new(Stub))
        }
    }

    /// FSR 1 that always works.
    struct Fsr1;

    impl Backend<FakeHost> for Fsr1 {
        fn kind(&self) -> UpscalerKind {
            UpscalerKind::Fsr1
        }
        fn probe(&self, _: &FakeHost) -> Result<(), UpscaleError> {
            Ok(())
        }
        fn create(&self, _: &FakeHost) -> Result<Box<dyn Upscaler>, UpscaleError> {
            Ok(Box::new(Stub))
        }
    }

    /// A library that records its calls and can fail at initialisation.
    struct Mock {
        create_code: u32,
        calls: Mutex<Vec<String>>,
    }

    impl Mock {
        fn new(create_code: u32) -> Arc<Self> {
            Arc::new(Self {
                create_code,
                calls: Mutex::default(),
            })
        }
    }

    impl FfxApi for Mock {
        unsafe fn create_context(
            &self,
            context: &mut ffx::ffxContext,
            desc: *mut ffx::ffxApiHeader,
        ) -> u32 {
            // SAFETY: the caller passes the chain built by `CreateDescs`.
            let (upscale, backend) = unsafe {
                let upscale = &*(desc as *const ffx::ffxCreateContextDescUpscale);
                let backend = &*(upscale.header.pNext as *const ffx::ffxCreateBackendVKDesc);
                (upscale, backend)
            };
            self.calls.lock().unwrap().push(format!(
                "create {:#x} {:#x} {:#x} device {:#x} {}x{}",
                upscale.header.type_,
                backend.header.type_,
                upscale.flags,
                backend.vkDevice.as_raw(),
                upscale.maxUpscaleSize.width,
                upscale.maxUpscaleSize.height,
            ));
            if self.create_code == ffx::FFX_API_RETURN_OK {
                *context = NonNull::<u8>::dangling().as_ptr().cast();
            }
            self.create_code
        }
        unsafe fn destroy_context(&self, _context: &mut ffx::ffxContext) -> u32 {
            self.calls.lock().unwrap().push("destroy".into());
            ffx::FFX_API_RETURN_OK
        }
        unsafe fn query(
            &self,
            _context: &mut ffx::ffxContext,
            _desc: *mut ffx::ffxApiHeader,
        ) -> u32 {
            self.calls.lock().unwrap().push("query".into());
            ffx::FFX_API_RETURN_ERROR
        }
        unsafe fn dispatch(
            &self,
            _context: &mut ffx::ffxContext,
            _desc: *const ffx::ffxApiHeader,
        ) -> u32 {
            ffx::FFX_API_RETURN_OK
        }
    }

    fn registry(fsr3: Fsr3Backend) -> Registry<FakeHost> {
        let mut r = Registry::new();
        r.register(Box::new(Fsr1));
        r.register(Box::new(fsr3));
        r
    }

    fn mocked(mock: &Arc<Mock>) -> Fsr3Backend {
        let mock = Arc::clone(mock);
        Fsr3Backend::with_loader(Box::new(move || Ok(Arc::clone(&mock) as Arc<dyn FfxApi>)))
    }

    #[test]
    fn a_missing_library_is_unavailable() {
        let err = load_from(Path::new("/nonexistent/amd_fidelityfx_vk.dll"))
            .err()
            .expect("no library there");
        assert!(matches!(
            err,
            UpscaleError::Unavailable {
                kind: UpscalerKind::Fsr3,
                ..
            }
        ));
        // Linux: never loaded at all.
        if !SUPPORTED_PLATFORM {
            assert!(load_system().is_err());
        }
    }

    #[test]
    fn without_the_library_the_selection_falls_back_to_fsr1() {
        // The test executable has no FidelityFX library next to it.
        let r = registry(Fsr3Backend::system());
        assert_eq!(r.available(&FakeHost), [UpscalerKind::Fsr1]);
        let made = r.create(UpscalerKind::Fsr3, &FakeHost).unwrap();
        assert_eq!(made.requested, UpscalerKind::Fsr3);
        assert_eq!(made.kind, UpscalerKind::Fsr1);
        assert!(made.fell_back());
    }

    #[test]
    fn a_library_failing_at_init_falls_back_to_fsr1() {
        let mock = Mock::new(ffx::FFX_API_RETURN_ERROR_RUNTIME_ERROR);
        let r = registry(mocked(&mock));
        assert_eq!(r.available(&FakeHost), [UpscalerKind::Fsr1]);
        let made = r.create(UpscalerKind::Fsr3, &FakeHost).unwrap();
        assert_eq!(made.kind, UpscalerKind::Fsr1);
        assert!(made.fell_back());
        // Init was attempted (twice: `available`, then `create`); no context
        // was left to destroy.
        let calls = mock.calls.lock().unwrap();
        assert_eq!(calls.len(), 2, "{calls:?}");
        assert!(calls.iter().all(|c| c.starts_with("create")), "{calls:?}");
    }

    #[test]
    fn a_working_library_is_selected() {
        let mock = Mock::new(ffx::FFX_API_RETURN_OK);
        let r = registry(mocked(&mock));
        assert_eq!(
            r.available(&FakeHost),
            [UpscalerKind::Fsr1, UpscalerKind::Fsr3]
        );
        let made = r.create(UpscalerKind::Fsr3, &FakeHost).unwrap();
        assert_eq!(made.kind, UpscalerKind::Fsr3);
        assert!(!made.fell_back());
        let calls = mock.calls.lock().unwrap();
        let create = format!(
            "create {:#x} {:#x} {:#x} device 0x10 64x64",
            ffx::FFX_API_CREATE_CONTEXT_DESC_TYPE_UPSCALE,
            ffx::FFX_API_CREATE_CONTEXT_DESC_TYPE_BACKEND_VK,
            mapping::create_flags(),
        );
        // Each probe creates, queries and destroys a small context.
        let probe = [create.as_str(), "query", "destroy"];
        assert_eq!(calls.len(), 6, "{calls:?}");
        assert_eq!(calls[..3], probe);
        assert_eq!(calls[3..], probe);
    }
}
